using System;using System.IO;using System.Linq;using System.Text;using System.Windows;using System.Windows.Automation;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Threading;
namespace SeraphimLuxury {
 static class Design13Tests {
  static void Check(bool v,string m){if(!v)throw new Exception(m);}
  static void Click(Button b){b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
  public static int Run(string directory){Directory.CreateDirectory(directory);var app=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};var prefs=Preferences.Defaults();prefs.Premium=true;prefs.ReducedMotion=true;var store=new PreferenceStore(Path.Combine(directory,"preferences.json"));store.Save(prefs);var w=new MainWindow(store,true){Opacity=0,ShowInTaskbar=false};app.MainWindow=w;int stage=0;var log=new StringBuilder();EyeLogo eye=null;Window eyeWindow=null;double angle=0;var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(300)};timer.Tick+=delegate {try{switch(stage++){
   case 0:w.UpdateLayout();Check(!w.countriesPopup13.IsOpen,"Pays repliés au démarrage");Check(w.studioDestination.ActualHeight<340,"Destination compacte");Check(!ToolsTests.Descend(w.studioDestination).OfType<EyeLogo>().Any(),"Aucun second logo dans Destination");Check(w.chromeSearch.BorderThickness.Left==0&&((SolidColorBrush)w.chromeSearch.Background).Color.A==0,"Recherche sans fond ni contour");Check(!ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().First(f=>f.Key.EndsWith("Composition & exploration")).Open,"Commandes de carte repliées");w.Capture(Path.Combine(directory,"home.png"));Click(w.countryDisclosure);break;
   case 1:Check(w.countriesPopup13.IsOpen&&w.visibleCountries.Items.Count==241,"Déroulement réel des pays");w.visibleCountries.SelectedItem=AtlasData.Countries.First(c=>c.id=="FRA");Check(!w.countriesPopup13.IsOpen&&w.atlas.Selected.id=="FRA","Choix pays et fermeture");Click(w.atlasOptionsButton);w.UpdateLayout();Check(ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().First(f=>f.Key.EndsWith("Composition & exploration")).Open,"Outils carte accessibles au clic");w.Capture(Path.Combine(directory,"home-options.png"));w.ShowPage("Réglages");break;
   case 2:var folds=ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().ToArray();Check(folds.Length>=6&&folds.All(f=>!f.Open),"Groupes illustrés repliés");w.Capture(Path.Combine(directory,"settings.png"));var content=folds.First(f=>AutomationProperties.GetName(f.Header)=="Contenu & applications");Click(content.Header);w.UpdateLayout();Check(content.Body.ActualHeight>150,"Les options se révèlent réellement");var adult=ToolsTests.Descend(content).OfType<CheckBox>().Single(c=>AutomationProperties.GetName(c)=="Contenus sensibles / 18+");adult.IsChecked=false;Check(!store.Load().AdultFilter,"Réglage réel conservé sous le dépliant");w.Capture(Path.Combine(directory,"settings-expanded.png"));w.ShowPage("Applications");break;
   case 3:var menu=ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().Single(f=>AutomationProperties.GetName(f.Header)=="☰  Applications");Check(!menu.Open,"Catalogue applications sur menu");Click(menu.Header);var rules=ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().Single(f=>AutomationProperties.GetName(f.Header)=="Règles de l’application");Click(rules.Header);w.UpdateLayout();var today=ToolsTests.Descend(w.ToolsPage).OfType<TextBlock>().Single(t=>t.Text.StartsWith("Aujourd’hui"));var remove=ToolsTests.Descend(w.ToolsPage).OfType<Button>().Single(b=>AutomationProperties.GetName(b)=="Retirer de cette liste");Point a=today.TranslatePoint(new Point(),(UIElement)w.ToolsPage),bpos=remove.TranslatePoint(new Point(),(UIElement)w.ToolsPage);Check(bpos.Y>=a.Y+today.ActualHeight+15,"Aujourd’hui et Retirer ne se chevauchent pas");Check(ToolsTests.Descend(w.ToolsPage).OfType<ScrollViewer>().Any(s=>s.IsVisible),"Catalogue défilant ouvert");w.Capture(Path.Combine(directory,"applications.png"));w.ShowPage("Accueil");w.OrbitalBottom13();break;
   case 4:w.Capture(Path.Combine(directory,"dashboard.png"));w.ShowPage("Checklist");Check(ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().Count()==2,"Checklist en deux panneaux");w.Capture(Path.Combine(directory,"checklist.png"));w.ShowPage("Planning");Check(ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().Count()==2,"Planning en panneaux");w.Capture(Path.Combine(directory,"planning.png"));w.ShowPage("Calendrier");w.Capture(Path.Combine(directory,"calendar.png"));w.Width=980;w.Height=680;w.ShowPage("Applications");break;
   case 5:w.Capture(Path.Combine(directory,"applications-minimum.png"));Visuals.ReducedMotion=false;eye=new EyeLogo(true,true);eyeWindow=new Window {Width=280,Height=280,Opacity=0,ShowInTaskbar=false,Content=new Viewbox {Child=eye}};eyeWindow.Show();Branding.SetSession(false);angle=eye.WingAngle;break;
   case 6:Check(Math.Abs(eye.WingAngle-angle)<.1,"Ailes au repos en veille");eye.Session(true);angle=eye.WingAngle;break;
   case 7:Check(eye.WingAngle>angle+2,"Deux ailes tournent pendant la session");Check(eye.RenderTransform.Value.IsIdentity,"Le logo complet et son œil ne tournent pas");Branding.Capture((FrameworkElement)eyeWindow.Content,Path.Combine(directory,"eye-active.png"));eye.Session(false);angle=eye.WingAngle;break;
   case 8:Check(Math.Abs(eye.WingAngle-angle)<.1,"Désactivation arrête les ailes");eyeWindow.Close();w.chromeSearch.Text="Instagram";Check(w.CurrentPage=="Applications"&&ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().First().Open,"La recherche révèle le catalogue filtré");Check(ToolsTests.Descend(w.ToolsPage).OfType<TextBlock>().Any(t=>t.Text=="Instagram"),"Instagram disponible dans la recherche");w.chromeSearch.Text="";w.ShowPage("Réglages");var animated=ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().First();animated.SetOpen(false,false);animated.SetOpen(true,true);break;
   case 9:var expanded=ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().First();Check(expanded.Body.ActualHeight>150&&Double.IsNaN(expanded.Body.Height),"Ouverture animée termine à hauteur automatique");expanded.SetOpen(false,true);expanded.SetOpen(true,true);expanded.SetOpen(false,true);break;
   case 10:Check(ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().First().Body.Visibility==Visibility.Collapsed,"Clics rapides sans état intermédiaire bloqué");Check(ToolsTests.Descend(w).OfType<System.Windows.Controls.Primitives.ScrollBar>().Where(b=>b.Orientation==Orientation.Vertical&&b.IsVisible).All(b=>b.Width==5),"Barres de défilement fines");w.Deactivate();timer.Stop();w.Close();log.AppendLine("PASS destination compacte, pays au clic, sélection réelle, commandes de carte repliées, recherche sans cadre.");log.AppendLine("PASS réglages illustrés extensibles et persistants, catalogue sur menu, espaces sans chevauchement Aujourd’hui/Retirer, checklist/planning/calendrier, 980x680.");log.AppendLine("PASS ailes en rotation indépendante en session active, œil non tournant, arrêt en veille, ouverture animée, clics rapides et défilement fin.");File.WriteAllText(Path.Combine(directory,"design-test.txt"),log.ToString());app.Shutdown();break;
  }}catch(Exception e){timer.Stop();if(eyeWindow!=null)eyeWindow.Close();w.Close();File.WriteAllText(Path.Combine(directory,"design-test.txt"),"FAIL stage "+stage+" "+e);app.Shutdown(1);}};w.Loaded+=delegate{timer.Start();};return app.Run(w);}
 }
 partial class MainWindow {internal void OrbitalBottom13(){var scroll=ToolsTests.Descend(shell).OfType<ScrollViewer>().First(s=>s.Content==page);scroll.ScrollToVerticalOffset(900);} }
}
